def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column('activity_log', sa.Column('product_id', sa.Integer(), nullable=True))
    op.create_index(op.f('ix_activity_log_product_id'), 'activity_log', ['product_id'], unique=False)
    op.create_foreign_key('fk_activity_log_product_id', 'activity_log', 'products', ['product_id'], ['id'], ondelete='SET NULL')
    # ### end Alembic commands ###

    # Piece goods were not journalled before: copy the existing movements into
    # the journal with their author and time, so past issues show up too.
    # "quantity_after" is unknown for them and is left out.
    op.execute("""
        INSERT INTO activity_log (created_at, user_id, action, product_id, quantity, length_mm, details)
        SELECT m.created_at,
               m.user_id,
               CASE WHEN m.quantity_changed > 0 THEN 'product_receive' ELSE 'product_issue' END,
               m.product_id,
               abs(m.quantity_changed),
               0,
               jsonb_strip_nulls(jsonb_build_object(
                   'product_name', p.name,
                   'product_type', t.name,
                   'assembly_id', m.assembly_id,
                   'from_movements', true
               ))
        FROM movements m
        JOIN products p ON p.id = m.product_id
        LEFT JOIN product_types t ON t.id = p.product_type_id
        WHERE m.quantity_changed <> 0
        ORDER BY m.id
    """)


